def test_bare_inheritance_from_slots():

    @attr.s(init=False, eq=False, order=False, unsafe_hash=False, repr=False, slots=True)
    class C1BareSlots:
        x = attr.ib(validator=attr.validators.instance_of(int))
        y = attr.ib()

        def method(self):
            return self.x

        @classmethod
        def classmethod(cls):
            return 'clsmethod'

        @staticmethod
        def staticmethod():
            return 'staticmethod'

    @attr.s(init=False, eq=False, order=False, unsafe_hash=False, repr=False)
    class C1Bare:
        x = attr.ib(validator=attr.validators.instance_of(int))
        y = attr.ib()

        def method(self):
            return self.x

        @classmethod
        def classmethod(cls):
            return 'clsmethod'

        @staticmethod
        def staticmethod():
            return 'staticmethod'

    @attr.s(slots=True, unsafe_hash=True)
    class C2Slots(C1BareSlots):
        z = attr.ib()

    @attr.s(slots=True, unsafe_hash=True)
    class C2(C1Bare):
        z = attr.ib()
    c2 = C2Slots(x=1, y=2, z='test')
    assert 1 == c2.x
    assert 2 == c2.y
    assert 'test' == c2.z
    assert 1 == c2.method()
    assert 'clsmethod' == c2.classmethod()
    assert 'staticmethod' == c2.staticmethod()
    with pytest.raises(AttributeError):
        c2.t = 'test'
    non_slot_instance = C2(x=1, y=2, z='test')
    if has_pympler:
        assert asizeof(c2) < asizeof(non_slot_instance)
    c3 = C2Slots(x=1, y=3, z='test')
    assert c3 > c2
    c2_ = C2Slots(x=1, y=2, z='test')
    assert c2 == c2_
    assert "C2Slots(x=1, y=2, z='test')" == repr(c2)
    hash(c2)
    assert {'x': 1, 'y': 2, 'z': 'test'} == attr.asdict(c2)
