/** Resolves the current default `QueryClient` registered by a connected `QueryClientProvider`. This helper is useful outside a Lit reactive controller when a single provider is mounted. It throws if no client is registered or if multiple clients are mounted and the default would be ambiguous. */
export function useQueryClient(): QueryClient {
  const client = getDefaultQueryClient()
  if (client) {
    return client
  }

  if (registeredClients.size > 1) {
    throw createAmbiguousQueryClientError()
  }

  throw createMissingQueryClientError()
}
