/// Pushes the current indentation level to the stack and sets the new level if [column] is greater than [_indent]. If it is, appends or inserts the specified token into [_tokens]. If [tokenNumber] is provided, the corresponding token will be replaced; otherwise, the token will be added at the end.
void _rollIndent(int column, TokenType type, SourceLocation location,
    {int? tokenNumber}) {
  if (!_inBlockContext) return;
  if (_indent != -1 && _indent >= column) return;

  // Push the current indentation level to the stack and set the new
  // indentation level.
  _indents.add(column);

  // Create a token and insert it into the queue.
  var token = Token(type, location.pointSpan() as FileSpan);
  if (tokenNumber == null) {
    _tokens.add(token);
  } else {
    _tokens.insert(tokenNumber - _tokensParsed, token);
  }
}
