/// The engine's standard update traversal: update this component, then update the children in priority order. Used for components without a [CustomTraversal], and as the default behavior of [CustomTraversal.updateSubtree].
void _defaultUpdateSubtree(double dt) {
  update(dt);
  final children = _children;
  if (children != null) {
    // The update pass doubles as the safe point where tombstones left by
    // removals since the last tick are compacted away.
