    let processID = GetCurrentProcessId()
    let threadID = GetCurrentThreadId()
    let tickCount = GetTickCount64()
    let uniqueID = "\(processID)-\(threadID)-\(tickCount)"

    return "\(tempDir)nio-wakeup-\(uniqueID).sock"
}
